
.battle-panel {
  background: linear-gradient(180deg, rgba(196, 48, 48, 0.08) 0%, transparent 100%);
  border-bottom: 2px solid var(--c-blood-dark);
  padding: 8px 12px;
}

.battle-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.battle-icon {
  font-size: 1rem;
}

.battle-title {
  color: var(--c-blood);
  font-weight: bold;
  font-size: 0.9rem;
  letter-spacing: 2px;
  animation: pulse 1.5s ease-in-out infinite;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}

.round-badge {
  margin-left: auto;
  background: var(--c-stone);
  color: var(--c-bone);
  padding: 2px 8px;
  font-size: 0.75rem;
  border: 1px solid var(--c-dim);
}

.enemy-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.enemy-card {
  background: var(--c-stone);
  border: 1px solid var(--c-dim);
  padding: 6px 10px;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.enemy-name {
  font-weight: bold;
  color: var(--c-blood);
  font-size: 0.85rem;
  min-width: 60px;
}

.enemy-stats {
  display: flex;
  gap: 8px;
  font-size: 0.78rem;
  color: var(--c-mist);
}

.stat {
  white-space: nowrap;
}

.hp-bar-container {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 100px;
}

.hp-bar-track {
  flex: 1;
  height: 8px;
  background: var(--c-abyss);
  border: 1px solid var(--c-dim);
  overflow: hidden;
}

.hp-bar-fill {
  height: 100%;
  background: var(--c-blood);
  transition: width 0.4s ease;
}

.hp-bar-fill.critical {
  animation: hpPulse 0.8s ease-in-out infinite;
}

@keyframes hpPulse {
  0%,
  100% {
    background: var(--c-blood);
  }
  50% {
    background: var(--c-blood-dark);
  }
}

.hp-text {
  font-size: 0.72rem;
  color: var(--c-mist);
  white-space: nowrap;
  min-width: 48px;
  text-align: right;
}

.no-enemy {
  text-align: center;
  color: var(--c-mist);
  font-style: italic;
  padding: 6px;
  font-size: 0.82rem;
}
