
.tabs {
  display: flex;
  background-color: var(--c-stone);
  border-bottom: 2px solid var(--c-dim);
}

.tab-button {
  flex: 1;
  padding: 7px;
  border: none;
  background: transparent;
  color: var(--c-mist);
  font-size: 0.85rem;
  font-weight: bold;
  font-family: var(--font-dungeon);
  cursor: pointer;
  transition: all 0.2s;
  border-right: 1px solid var(--c-dim);
}

.tab-button:last-child {
  border-right: none;
}

.tab-button:hover {
  background-color: var(--c-dim);
  color: var(--c-bone);
}

.tab-button.active {
  background-color: var(--c-dark-stone);
  color: var(--c-gold);
  position: relative;
  top: 1px;
  padding-bottom: 9px;
}
