
.section-head {
  font-size: 0.88rem;
  border-bottom: 2px solid var(--c-gold);
  display: inline-block;
  margin-bottom: 8px;
  font-weight: bold;
  color: var(--c-gold);
}

.inv-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item-row {
  display: flex;
  align-items: center;
  border: 1px solid var(--c-dim);
  padding: 6px 8px;
  background: var(--c-stone);
  transition: border-color 0.2s;
}

.item-row:hover {
  border-color: var(--c-mist);
}

.item-icon {
  width: 26px;
  height: 26px;
  background: var(--c-abyss);
  border: 1px solid var(--c-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 8px;
  font-size: 0.85rem;
}

.item-detail {
  flex: 1;
}

.item-name {
  font-weight: bold;
  display: block;
  color: var(--c-bone);
  font-size: 0.82rem;
}

.item-desc {
  font-size: 0.72rem;
  color: var(--c-mist);
  display: block;
}

.item-owner {
  font-size: 0.65rem;
  color: var(--c-dim);
}

.item-count {
  background: var(--c-dim);
  color: var(--c-bone);
  padding: 1px 5px;
  font-size: 0.7rem;
  font-weight: bold;
}

.empty-state {
  text-align: center;
  color: var(--c-mist);
  padding: 16px;
  font-style: italic;
  font-size: 0.82rem;
}
