
.corruption-strip {
  padding: 6px 12px;
  background: rgba(154, 48, 112, 0.05);
  border-bottom: 1px solid var(--c-dim);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.corruption-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.name {
  font-size: 0.78rem;
  color: var(--c-parchment);
  min-width: 48px;
  font-weight: bold;
}

.bar-track {
  flex: 1;
  height: 6px;
  background: var(--c-abyss);
  border: 1px solid var(--c-corrupt-dim);
  overflow: hidden;
  max-width: 200px;
}

.bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--c-corrupt-dim), var(--c-corrupt));
  transition: width 0.4s ease;
}

.value {
  font-size: 0.72rem;
  color: var(--c-corrupt);
  font-weight: bold;
  min-width: 20px;
  text-align: right;
}

.stage {
  font-size: 0.68rem;
  color: var(--c-mist);
  padding: 1px 4px;
  border: 1px solid var(--c-dim);
  background: var(--c-stone);
}
