
.team-layout {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.player-card {
  background: var(--c-stone);
  border: 1px solid var(--c-dim);
  padding: 8px 10px;
  transition: border-color 0.2s;
}

.player-card:hover {
  border-color: var(--c-mist);
}

.player-card.dead {
  opacity: 0.4;
}

.player-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}

.player-name {
  font-weight: bold;
  color: var(--c-bone);
  font-size: 0.88rem;
}

.player-level {
  color: var(--c-gold);
  font-size: 0.72rem;
  font-weight: bold;
}

.player-status {
  margin-left: auto;
  font-size: 0.68rem;
  padding: 1px 5px;
  border: 1px solid;
}

.status-normal {
  color: var(--c-poison);
  border-color: var(--c-poison);
}

.status-injured {
  color: var(--c-gold);
  border-color: var(--c-gold);
}

.status-dying {
  color: var(--c-blood);
  border-color: var(--c-blood);
  animation: pulse 1.2s ease-in-out infinite;
}

.status-dead {
  color: var(--c-mist);
  border-color: var(--c-dim);
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

.stat-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}

.stat-row.compact {
  gap: 8px;
  margin-bottom: 4px;
}

.stat-label {
  font-size: 0.7rem;
  color: var(--c-mist);
  min-width: 18px;
}

.hp-track {
  flex: 1;
  height: 6px;
  background: var(--c-abyss);
  border: 1px solid var(--c-blood-dark);
  overflow: hidden;
}

.hp-fill {
  height: 100%;
  background: var(--c-blood);
  transition: width 0.4s ease;
}

.hp-fill.critical {
  animation: hpBlink 0.8s infinite;
}

@keyframes hpBlink {
  0%,
  100% {
    background: var(--c-blood);
  }
  50% {
    background: var(--c-blood-dark);
  }
}

.stat-value {
  font-size: 0.72rem;
  color: var(--c-parchment);
  min-width: 42px;
  text-align: right;
}

.hp-value {
  color: var(--c-blood);
}

.stat-chip {
  font-size: 0.72rem;
  color: var(--c-parchment);
  background: var(--c-abyss);
  padding: 1px 5px;
  border: 1px solid var(--c-dim);
}

.stat-chip.exp {
  color: var(--c-gold);
}

.skill-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.skill-name {
  font-size: 0.78rem;
  color: var(--c-mist);
}

.skill-name.active {
  color: var(--c-arcane);
}

.skill-lv {
  font-size: 0.65rem;
  color: var(--c-arcane-dim);
}

.skill-tag {
  font-size: 0.65rem;
  padding: 1px 4px;
  border: 1px solid;
}

.active-tag {
  color: var(--c-arcane);
  border-color: var(--c-arcane-dim);
  background: rgba(106, 90, 205, 0.1);
}

.cd-tag {
  color: var(--c-frost);
  border-color: var(--c-frost);
  opacity: 0.7;
}

.ready-tag {
  color: var(--c-poison);
  border-color: var(--c-poison);
}

.empty {
  text-align: center;
  color: var(--c-mist);
  padding: 16px;
  font-style: italic;
}
