
.header {
  padding: 10px 12px;
  background: linear-gradient(180deg, rgba(42, 42, 58, 0.9) 0%, var(--c-dark-stone) 100%);
  border-bottom: 2px solid var(--c-dim);
}

.title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.tower-icon {
  font-size: 1.2rem;
}

.tower-name {
  font-size: 1.1rem;
  font-weight: bold;
  color: var(--c-bone);
  letter-spacing: 4px;
}

.floor-badge {
  margin-left: auto;
  background: var(--c-blood);
  color: #fff;
  padding: 2px 8px;
  font-weight: bold;
  font-size: 0.85rem;
  border: 1px solid var(--c-blood-dark);
}

.info-row {
  display: flex;
  gap: 12px;
  padding-bottom: 6px;
  margin-bottom: 6px;
  border-bottom: 1px dashed var(--c-dim);
  flex-wrap: wrap;
}

.info-item {
  display: flex;
  gap: 4px;
  align-items: center;
}

.label {
  color: var(--c-mist);
  font-size: 0.75rem;
}

.value {
  color: var(--c-bone);
  font-weight: bold;
  font-size: 0.82rem;
}

.phase-combat {
  color: var(--c-blood) !important;
}

.phase-explore {
  color: var(--c-frost) !important;
}

.phase-event {
  color: var(--c-gold) !important;
}

.phase-rest {
  color: var(--c-poison) !important;
}

.team-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.survivors {
  display: flex;
  gap: 3px;
}

.dot {
  width: 8px;
  height: 8px;
  background: var(--c-poison);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.dot.dead {
  background: var(--c-blood-dark);
  opacity: 0.5;
}

.count {
  color: var(--c-bone);
  font-weight: bold;
  font-size: 0.8rem;
}

.dead-list {
  color: var(--c-blood);
  font-size: 0.75rem;
  font-style: italic;
}
